arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" --data "token=<TOKEN>&types=public_channel&limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR:', d); sys.exit(1)
for c in d['channels']:
    if c['name'] in ('launch-plan',):
        print(c['id'], c['name'])
"

